/**
 * Local thumbnail resolution (MISSION-017). The manifest is generated by
 * scripts/build-thumbs.mjs from the committed fixtures — a baked WebP beats
 * shipping the full-resolution original into a 240px card by ~10x.
 * No fs at runtime (the Worker has none): the manifest is imported JSON.
 */

import baked from '../generated/local-thumbs.json';

const LOCAL = new Set<string>(baked as string[]);

/** The 480px local WebP when baked; the remote original otherwise. */
export function thumbSrc(assetId: string, remoteUrl: string | null): string | null {
  if (LOCAL.has(assetId)) return `/thumbs/${assetId}.webp`;
  return remoteUrl;
}

/**
 * A baked card picture's srcset (v0.89.0): a screen of density 1 takes the
 * 1x cut — about a third of the bytes, still covering the widest card — and
 * any denser screen the 480px one. Null for a remote picture: it has one size.
 */
export function thumbSrcSet(assetId: string): string | null {
  if (!LOCAL.has(assetId)) return null;
  return `/thumbs/1x/${assetId}.webp 1x, /thumbs/${assetId}.webp 2x`;
}
